# Replace the illustrated hero with a real photographic slideshow plus a short, sourced client quote.
hero='''<div class="hero-art reveal delay2"><div class="hero-photo-stage" id="home-photo-stage"><img class="stage-photo" id="stage-photo" src="assets/chicago-skyline.jpg" alt="Chicago skyline over Lake Michigan" width="2200" height="1467"><div class="stage-shade"></div><div class="stage-review"><span>CLIENT WORDS</span><blockquote id="stage-quote">“John is as good as it gets for small business and personal accounting.”</blockquote><b id="stage-reviewer">Joe B.</b></div><div class="stage-controls"><button type="button" id="stage-prev" aria-label="Previous featured image and review">←</button><span id="stage-count" aria-live="polite">01 / 03</span><button type="button" id="stage-next" aria-label="Next featured image and review">→</button></div></div></div>'''
