assert n==1, f'hero match {n}'

# Give the image-rich sections distinct real photographs, and place photo credits on the page.
s=s.replace('.hero{position:relative;background:#e9efe7 url("assets/chicago-evening.svg") center/cover no-repeat;isolation:isolate}', '.hero{position:relative;background:#e9efe7 url("assets/chicago-skyline.jpg") center 54%/cover no-repeat;isolation:isolate}')
s=s.replace('.hero-scene{position:absolute;inset:16px 0 0 20px;width:calc(100% - 20px);height:calc(100% - 16px);object-fit:cover;border-radius:44% 44% 3px 3px;box-shadow:0 22px 58px #223a2c25;animation:sceneDrift 24s ease-in-out infinite alternate}.ledger-scene{position:absolute;width:57%;height:auto;right:-2%;bottom:1%;filter:drop-shadow(0 20px 20px #1a1d1b30);animation:float 7s ease-in-out infinite}', '.hero-photo-stage{position:absolute;inset:16px 0 0 20px;overflow:hidden;border-radius:44% 44% 3px 3px;box-shadow:0 22px 58px #223a2c35;background:#243c35}.stage-photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;animation:photoDrift 18s ease-in-out infinite alternate;transition:opacity .8s,transform 1.2s}.stage-photo.changing{opacity:.2;transform:scale(1.11)}.stage-shade{position:absolute;inset:0;background:linear-gradient(180deg,#07170e00 28%,#07170edb 100%)}.stage-review{position:absolute;left:clamp(20px,5%,48px);right:20px;bottom:76px;color:#fff;max-width:520px;text-shadow:0 2px 15px #0008;animation:stageEnter .7s var(--ease)}.stage-review span{font-size:10px;letter-spacing:.19em;font-weight:700;color:#e8ca88}.stage-review blockquote{font:500 clamp(19px,2.2vw,27px)/1.4 var(--serif);margin:11px 0}.stage-review b{font-size:12px}.stage-controls{position:absolute;bottom:20px;left:clamp(20px,5%,48px);display:flex;align-items:center;gap:15px;color:white;font-size:11px;letter-spacing:.12em}.stage-controls button{width:38px;height:38px;border:1px solid #ffffff96;border-radius:50%;color:#fff;background:#ffffff1a;cursor:pointer;transition:background .2s,transform .2s}.stage-controls button:hover{background:#ffffff3a;transform:scale(1.08)}')
s=s.replace('.services-full{background:#e6ede3;padding-top:74px;padding-bottom:74px}', '.services-full{background:linear-gradient(90deg,#e6ede3f7 0%,#e6ede3ee 58%,#e6ede3a1 100%),url("assets/accounting-workspace.jpg") right center/cover no-repeat;padding-top:74px;padding-bottom:74px}')
