s=s.replace('.first-meeting{background:#f0eee7}', '.first-meeting{background:linear-gradient(90deg,#f0eee7f4 0%,#f0eee7ed 66%,#f0eee7a8 100%),url("assets/chicago-buildings.jpg") center/cover no-repeat}')
