extra_css='''
    @keyframes photoDrift{from{transform:scale(1.01) translateX(-.5%)}to{transform:scale(1.09) translateX(.5%)}}@keyframes stageEnter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
    .proof{position:relative;background:linear-gradient(90deg,#ecefe8f5,#ecefe8ee 70%,#ecefe8c9),url("assets/accounting-workspace.jpg") right center/cover no-repeat}.review-card{transition:opacity .45s,transform .45s}.review-card.revolving{animation:stageEnter .55s var(--ease)}
    .footer-social{display:flex;align-items:center;gap:10px}.social-link{width:35px;height:35px;display:grid;place-items:center;border:1px solid #c8d0c6;border-radius:50%;color:var(--green);transition:background .2s,color .2s,transform .2s}.social-link:hover{background:var(--green);color:white;transform:translateY(-3px)}.social-link svg{width:15px;height:15px;fill:currentColor}
    .photo-credit{font-size:10px;color:#b9c8bd;text-align:center;margin:8px auto 0}.photo-credit a{text-decoration:underline;text-underline-offset:2px}
    .assistant-launcher{position:fixed;z-index:40;right:24px;bottom:24px;width:64px;height:64px;border:0;border-radius:50%;background:var(--green);color:#fff;box-shadow:0 12px 34px #142f2455;display:grid;place-items:center;cursor:pointer;transition:transform .25s,box-shadow .25s}.assistant-launcher:hover{transform:translateY(-4px) scale(1.03);box-shadow:0 18px 42px #142f2466}.assistant-launcher svg{width:28px;height:28px;fill:none;stroke:currentColor;stroke-width:1.8}.assistant-launcher .assistant-ping{position:absolute;right:2px;top:2px;width:13px;height:13px;border:2px solid white;border-radius:50%;background:#8dc79c;box-shadow:0 0 0 4px #8dc79c35;animation:pulse 2.2s infinite}
    .assistant-panel{position:fixed;z-index:41;right:24px;bottom:101px;width:min(410px,calc(100vw - 28px));height:min(640px,calc(100dvh - 130px));display:flex;flex-direction:column;background:#fbfcf9;border:1px solid #d6dfd5;border-radius:16px;box-shadow:0 24px 72px #172b2252;overflow:hidden;transform-origin:bottom right;animation:assistantIn .25s var(--ease)}.assistant-panel[hidden]{display:none}.assistant-head{display:flex;align-items:center;gap:12px;padding:16px;background:var(--green);color:#fff}.assistant-avatar{width:38px;height:38px;object-fit:cover;background:#fff;border-radius:9px}.assistant-title{flex:1;min-width:0}.assistant-title strong{display:block;font:600 15px var(--serif)}.assistant-title small{display:block;font-size:10px;color:#d7e5da}.assistant-head button{border:0;background:transparent;color:#fff;font-size:22px;cursor:pointer;width:34px;height:34px}.assistant-messages{flex:1;overflow:auto;padding:18px 15px;display:flex;flex-direction:column;gap:12px;scroll-behavior:smooth}.assistant-msg{max-width:90%;padding:11px 13px;border-radius:12px;font-size:13px;line-height:1.5;white-space:pre-wrap;overflow-wrap:anywhere}.assistant-msg.bot{align-self:flex-start;background:#edf1eb;color:var(--ink);border-bottom-left-radius:3px}.assistant-msg.user{align-self:flex-end;background:var(--green);color:#fff;border-bottom-right-radius:3px}.assistant-msg.pending{opacity:.7}.assistant-suggestions{padding:0 14px 12px;display:flex;gap:7px;overflow:auto}.assistant-suggestions button{white-space:nowrap;border:1px solid #b9cabb;background:#fff;border-radius:20px;padding:8px 11px;color:var(--green);font-size:11px;cursor:pointer}.assistant-input-row{display:flex;gap:8px;padding:12px;border-top:1px solid #dfe5dc;background:#fff}.assistant-input-row input{min-width:0;flex:1;border:1px solid #d3ddd2;border-radius:24px;padding:11px 14px;font:inherit;font-size:13px;outline-color:var(--green)}.assistant-input-row button{width:42px;height:42px;border:0;border-radius:50%;background:var(--brick);color:white;font-size:19px;cursor:pointer}.assistant-privacy{padding:0 14px 10px;background:#fff;color:#667168;font-size:9px}.assistant-source{display:block;margin-top:7px;color:var(--green);font-size:10px}.assistant-offline{font-size:12px}.assistant-form-status{min-height:15px;font-size:10px;color:#58645a;text-align:center;margin:0 12px 8px}.assistant-panel a{color:var(--green)}
    @keyframes assistantIn{from{opacity:0;transform:translateY(12px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
    @media(max-width:600px){.assistant-launcher{right:14px;bottom:78px;width:58px;height:58px}.assistant-panel{right:8px;bottom:145px;width:calc(100vw - 16px);height:min(70dvh,620px);border-radius:14px}.footer-social{gap:7px}.footer-row{padding-bottom:12px}.stage-review{left:20px;bottom:67px}.stage-controls{left:20px}.hero-photo-stage{inset:10px 0 0 2px}}
    @media(prefers-reduced-motion:reduce){.stage-photo,.assistant-launcher,.social-link{animation:none;transition:none}.assistant-panel{animation:none}}
'''
s=s.replace('</style>',extra_css+'\n  </style>',1)

# Verified social URLs from the firm's own live homepage.
social='''<div class="footer-social" aria-label="Social media"><a class="social-link" href="https://www.facebook.com/chicagoaccountingfirm/" aria-label="Facebook" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.5 21v-8h2.7l.4-3.1h-3.1v-2c0-.9.3-1.5 1.6-1.5h1.7V3.6c-.3 0-1.3-.1-2.5-.1-2.5 0-4.2 1.5-4.2 4.3v2.1H7.3V13h2.8v8h3.4Z"/></svg></a><a class="social-link" href="https://twitter.com/johnjgriffincpa" aria-label="Twitter" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M22 5.9a8 8 0 0 1-2.4.7 4.2 4.2 0 0 0 1.8-2.3 8.4 8.4 0 0 1-2.7 1 4.2 4.2 0 0 0-7.2 3.8 11.9 11.9 0 0 1-8.6-4.4 4.2 4.2 0 0 0 1.3 5.6 4.2 4.2 0 0 1-1.9-.5v.1a4.2 4.2 0 0 0 3.4 4.1 4 4 0 0 1-1.9.1 4.2 4.2 0 0 0 3.9 2.9A8.4 8.4 0 0 1 2.5 19a11.8 11.8 0 0 0 18.2-10 8.5 8.5 0 0 0 2-2.1Z"/></svg></a><a class="social-link" href="https://www.linkedin.com/in/johngriffincpa" aria-label="LinkedIn" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5.1 3.5a2 2 0 1 0 0 4.1 2 2 0 0 0 0-4.1ZM3.4 9h3.4v11H3.4V9Zm5.5 0h3.3v1.5h.1a3.6 3.6 0 0 1 3.2-1.8c3.5 0 4.1 2.3 4.1 5.2V20h-3.4v-5.4c0-1.3 0-3-1.8-3s-2.1 1.4-2.1 2.9V20H8.9V9Z"/></svg></a></div>'''
s=s.replace('<div class="footer-links">', '<div class="footer-links">', 1)
s=s.replace('</div></div></footer>\n  <div class="mobile-bar"', '</div>'+social+'</div></div></footer>\n  <div class="mobile-bar"',1)

# Persistent assistant UI; all business replies are delegated to the secured same-origin API.
chat='''<div class="assistant-widget"><button class="assistant-launcher" id="assistant-launcher" type="button" aria-label="Open Griffin business assistant" aria-expanded="false" aria-controls="assistant-panel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11.5a7.5 7.5 0 0 1-7.5 7.5H6l-3 2v-5.1A7.5 7.5 0 1 1 20 11.5Z"/><path d="M8 11h8M8 14h5"/></svg><i class="assistant-ping" aria-hidden="true"></i></button><section class="assistant-panel" id="assistant-panel" aria-label="Griffin Business Assistant" hidden><header class="assistant-head"><img class="assistant-avatar" src="assets/jjg-mark.png" alt=""><div class="assistant-title"><strong>Griffin Business Assistant</strong><small>Answers grounded in firm information</small></div><button type="button" id="assistant-close" aria-label="Close assistant">×</button></header><div class="assistant-messages" id="assistant-messages" role="log" aria-live="polite"><div class="assistant-msg bot">Hi, I can help with John Griffin CPA’s services, history, location, and contact details. Ask me anything.</div></div><div class="assistant-suggestions" id="assistant-suggestions"><button type="button">What services do you offer?</button><button type="button">Who is John Griffin?</button><button type="button">Where is the office?</button></div><p class="assistant-form-status" id="assistant-status" aria-live="polite">Business information is indexed when the assistant service is connected.</p><form class="assistant-input-row" id="assistant-form"><input id="assistant-input" name="message" maxlength="1200" autocomplete="off" placeholder="Ask about the firm…" aria-label="Your question" required><button type="submit" aria-label="Send message">↑</button></form><div class="assistant-privacy">Please don’t share Social Security numbers, tax documents, or other sensitive information.</div></section></div>'''
s=s.replace('  <div class="mobile-bar"',chat+'\n  <div class="mobile-bar"',1)

# Use short quotations only from the homepage and retain the fully paraphrased list below.
photo_js='''
    const stagePhotos = [
      {src:'assets/chicago-skyline.jpg', alt:'Chicago skyline across Lake Michigan', quote:'John is as good as it gets for small business and personal accounting.', reviewer:'Joe B.'},
      {src:'assets/accounting-workspace.jpg', alt:'A bright professional workspace', quote:'He is very accessible, honest and I would highly recommend his service!', reviewer:'Trista K.'},
      {src:'assets/construction-business.jpg', alt:'Construction professionals reviewing a building project', quote:'He wanted to meet us on our turf, in our business, to better serve us.', reviewer:'Joe B.'}
    ];
    let stageIndex=0;
    function showStage(next){const image=document.getElementById('stage-photo');const content=stagePhotos[next];image.classList.add('changing');window.setTimeout(()=>{image.src=content.src;image.alt=content.alt;document.getElementById('stage-quote').textContent='“'+content.quote+'”';document.getElementById('stage-reviewer').textContent=content.reviewer;document.getElementById('stage-count').textContent=String(next+1).padStart(2,'0')+' / 03';image.classList.remove('changing');stageIndex=next;},320)}
    document.getElementById('stage-next').addEventListener('click',()=>showStage((stageIndex+1)%stagePhotos.length));
    document.getElementById('stage-prev').addEventListener('click',()=>showStage((stageIndex+stagePhotos.length-1)%stagePhotos.length));
    if(!reduceMotion){window.setInterval(()=>showStage((stageIndex+1)%stagePhotos.length),7000)}
    const featured=[...document.querySelectorAll('.review-featured .review-card')];
    const allReviews=[...document.querySelectorAll('.review-card')].map(card=>({text:card.querySelector('p').textContent,author:card.querySelector('footer').childNodes[0].textContent.trim()}));
    let reviewOffset=0;
    if(!reduceMotion)window.setInterval(()=>{reviewOffset=(reviewOffset+featured.length)%allReviews.length;featured.forEach((card,index)=>{const review=allReviews[(reviewOffset+index)%allReviews.length];card.classList.remove('revolving');void card.offsetWidth;card.querySelector('p').textContent=review.text;card.querySelector('footer').childNodes[0].textContent=review.author+' ';card.classList.add('revolving')})},6500);
'''
s=s.replace("    const items = document.querySelectorAll('.reveal');",photo_js+"\n    const items = document.querySelectorAll('.reveal');",1)

assistant_js='''
    const assistantButton=document.getElementById('assistant-launcher');
    const assistantPanel=document.getElementById('assistant-panel');
    const assistantMessages=document.getElementById('assistant-messages');
    const assistantInput=document.getElementById('assistant-input');
    const assistantHistory=[];
    function toggleAssistant(open){assistantPanel.hidden=!open;assistantButton.setAttribute('aria-expanded',String(open));if(open)assistantInput.focus();}
    assistantButton.addEventListener('click',()=>toggleAssistant(assistantPanel.hidden));
    document.getElementById('assistant-close').addEventListener('click',()=>toggleAssistant(false));
    function addAssistantMessage(text,role){const node=document.createElement('div');node.className='assistant-msg '+role;node.textContent=text;assistantMessages.appendChild(node);assistantMessages.scrollTop=assistantMessages.scrollHeight;return node;}
    document.querySelectorAll('#assistant-suggestions button').forEach(button=>button.addEventListener('click',()=>{assistantInput.value=button.textContent;document.getElementById('assistant-form').requestSubmit()}));
    document.getElementById('assistant-form').addEventListener('submit',async event=>{
      event.preventDefault();const question=assistantInput.value.trim();if(!question)return;assistantInput.value='';addAssistantMessage(question,'user');assistantHistory.push({role:'user',content:question});
      const reply=addAssistantMessage('Looking through the firm information…','bot pending');const status=document.getElementById('assistant-status');status.textContent='Searching verified business information';
      try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:assistantHistory.slice(-10)})});if(!response.ok)throw new Error('Assistant service unavailable');
        if(!response.body)throw new Error('Streaming unavailable');const reader=response.body.getReader();const decoder=new TextDecoder();let buffer='';let answer='';
        while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const frames=buffer.split('\n\n');buffer=frames.pop()||'';for(const frame of frames){const dataLine=frame.split('\n').find(line=>line.startsWith('data:'));if(!dataLine)continue;const data=dataLine.slice(5).trim();if(data==='[DONE]')continue;const item=JSON.parse(data);if(item.delta){answer+=item.delta;reply.textContent=answer;assistantMessages.scrollTop=assistantMessages.scrollHeight;}if(item.error)throw new Error(item.error)}}
        if(!answer)throw new Error('No answer returned');reply.classList.remove('pending');assistantHistory.push({role:'assistant',content:answer});status.textContent='Answers are based on indexed firm information';
      }catch(error){reply.textContent='I’m having trouble connecting right now. Please try again in a moment, or call 773-545-6750 or email john@johngriffincpa.com for help.';reply.classList.remove('pending');status.textContent='Phone and email are available if the assistant is offline';assistantHistory.pop();}
    });
'''
s=s.replace("    const items = document.querySelectorAll('.reveal');",assistant_js+"\n    const items = document.querySelectorAll('.reveal');",1)

p.write_text(s,encoding='utf-8')
print('Updated photographic sections, social links, rotating reviews, and floating assistant UI.')
